import json, itertools, sys
obs={int(k):v for k,v in json.load(open('/tmp/braille_order.json')).items()}
# derive pairwise constraints: for each base, adds observed in order a1..ak (k<=5) ; all observed adds < all unobserved adds (if k<5 exactly, hmm: if fewer than 5 adds observed, then the removal neighbors occupy the rest; can't conclude much about unobserved adds except they're after the observed ones only if the list is full) 
cons=[]  # (lo_code, hi_code)
for base,seq in obs.items():
    if any(isinstance(s,tuple) for s in seq): continue
    adds=[base|(1<<k) for k in seq]
    for i in range(len(adds)-1): cons.append((adds[i],adds[i+1]))
    # neighbors not observed: adds not in seq; they must be after the last observed (if list was full = 5 neighbors incl removals)
    nrem=bin(base).count('1')
    if len(seq)+nrem>=5:
        # the first 5 neighbors are: all observed adds + (5-len(seq)) removals; unobserved adds come after
        for k in range(8):
            if (base>>k)&1: continue
            c=base|(1<<k)
            if c not in adds: cons.append((adds[-1],c))
print(len(cons),'constraints')
def check(key):
    for lo,hi in cons:
        if not key(lo)<key(hi): return False
    return True
found=0
for perm in itertools.permutations(range(8)):
    for inv in range(256):
        def key(code):
            x=code^inv; k=0
            for j in range(8):
                if (x>>j)&1: k|=1<<perm[j]
            return k
        if check(key):
            found+=1
            if found<=5: print('perm',perm,'inv',hex(inv))
print('found',found)
