    pop=bin(b).count('1')
    offs=[k for k in range(8) if not (b>>k)&1]
    U=[k for k in offs if k not in A]
    if len(A)+pop>=5:
        for a in A:
            for u in U:
                edges[b|(1<<a)].add(b|(1<<u))
    # also: removal count included = 5-|A| ; if 5-|A| < pop, then (pop-(5-|A|)) removals are after all included adds... unknown which.
# check cycles via topo sort
