env=dict(os.environ); env.pop('TERM',None)
def make(m, dark, bright, name, H=16):
    rows=[[dark]*8 for _ in range(H)]
    for y in range(H):
        for x in range(8): rows[y][x]= dark if x<4 else bright
    rows[0][1]=(m,m,m); rows[0][2]=(m,m,m)
    write_png(name, 8, H, [[(v[0],v[1],v[2],255) for v in r] for r in rows])
